// DmSqlParserInit initializes any static state used to implement DmSqlParser. By default the
// static state used to implement the parser is lazily initialized during the first call to
// NewDmSqlParser(). You can call this function if you wish to initialize the static state ahead
// of time.
func DmSqlParserInit() {
	staticData := &DmSqlParserParserStaticData
	staticData.once.Do(dmsqlparserParserInit)
}

// NewDmSqlParser produces a new parser instance for the optional input antlr.TokenStream.
func NewDmSqlParser(input antlr.TokenStream) *DmSqlParser {
	DmSqlParserInit()
	this := new(DmSqlParser)
	this.BaseParser = antlr.NewBaseParser(input)
	staticData := &DmSqlParserParserStaticData
	this.Interpreter = antlr.NewParserATNSimulator(this, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	this.RuleNames = staticData.RuleNames
	this.LiteralNames = staticData.LiteralNames
	this.SymbolicNames = staticData.SymbolicNames
	this.GrammarFileName = "DmSqlParser.g4"

	return this
}

